import {scenarioAllowsBackground} from './scenario-background-rules.js?v=civic-garbage-1';
import {recordHazard} from './emergency-order.js?v=civic-garbage-1';
import {beginEmergencySession} from './emergency-session.js?v=civic-garbage-1';
export const freshWhirlpool=()=>({randomWhirlpools:false,whirlpool:null,whirlpools:0});
export function startWhirlpool(c,x,y){const n=Math.sqrt(c.tiles.length),e=c.emergency;if(e.whirlpool)return{ok:false,error:'This disaster type is already active.'};if(!Number.isInteger(x)||!Number.isInteger(y)||x<0||y<0||x>=n||y>=n||c.tiles[y*n+x].terrain!=='water')return{ok:false,error:'Choose a water tile for the whirlpool.'};beginEmergencySession(c);recordHazard(e,'whirlpool');Object.assign(e,{whirlpool:{x,y,age:0}});e.whirlpools++;return{ok:true};}
// Four expanding pulses; only connected surface water and its immediate shore are exposed.
export function stepWhirlpool(c,damage){const e=c.emergency,s=e.whirlpool;if(!s)return 0;s.age++;let lost=0;if(s.age%6===0){const n=Math.sqrt(c.tiles.length),radius=s.age/6,water=new Set([s.y*n+s.x]),queue=[s.y*n+s.x];for(let k=0;k<queue.length;k++){const t=c.tiles[queue[k]];for(const [dx,dy]of [[1,0],[-1,0],[0,1],[0,-1]]){const x=t.x+dx,y=t.y+dy,i=y*n+x;if(x<0||y<0||x>=n||y>=n||water.has(i)||Math.hypot(x-s.x,y-s.y)>radius||c.tiles[i].terrain!=='water')continue;water.add(i);queue.push(i);}}const exposed=new Set(water);for(const i of water){const t=c.tiles[i];for(const [dx,dy]of [[1,0],[-1,0],[0,1],[0,-1]]){const x=t.x+dx,y=t.y+dy;if(x>=0&&y>=0&&x<n&&y<n)exposed.add(y*n+x);}}for(const i of exposed)lost+=damage(c,c.tiles[i]);}if(s.age>=24)e.whirlpool=null;return lost;}
export function validateWhirlpool(v,tiles,version){if(version<50)return freshWhirlpool();if(version>=51&&typeof v.randomWhirlpools!=='boolean')throw Error('Invalid random whirlpool setting.');if(!Number.isInteger(v.whirlpools)||v.whirlpools<0||v.whirlpools>1e9)throw Error('Invalid whirlpool history.');let whirlpool=null;if(v.whirlpool!==null){const s=v.whirlpool,n=Math.sqrt(tiles.length);if(!s||!v.active||!v.whirlpools||version<96&&['toxicCloud','spaceJunk','riot','locust','tornado','earthquake'].some(k=>v[k])||!Number.isInteger(s.age)||s.age<0||s.age>=24||['x','y'].some(k=>!Number.isInteger(s[k])||s[k]<0||s[k]>=n)||tiles[s.y*n+s.x].terrain!=='water')throw Error('Invalid whirlpool state.');whirlpool={x:s.x,y:s.y,age:s.age};}return{randomWhirlpools:version>=51?v.randomWhirlpools:false,whirlpool,whirlpools:v.whirlpools};}

export function setRandomWhirlpools(c,value){if(c.emergency.active)return{ok:false,error:'Finish the active emergency before changing disaster settings.'};if(typeof value!=='boolean')return{ok:false,error:'Choose a valid whirlpool setting.'};c.emergency.randomWhirlpools=value;return{ok:true};}
const roll=(month,seed,salt)=>{let h=Math.imul(month+salt,374761393)^Math.imul(seed+131,668265263);h=Math.imul(h^(h>>>13),1274126177);return((h^(h>>>16))>>>0)/4294967296;};
export function maybeWhirlpool(c){if(!scenarioAllowsBackground(c,'randomDisasters'))return false;if(!c.emergency.randomWhirlpools||c.emergency.active||roll(c.month,c.seed,137)>=.003)return false;const water=c.tiles.filter(t=>t.terrain==='water');if(!water.length)return false;const t=water[Math.floor(roll(c.month,c.seed,139)*water.length)];return startWhirlpool(c,t.x,t.y).ok;}
